package vn.xuannhashop.business.finance.application;
import java.util.*;
import java.math.BigDecimal;
import java.time.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import vn.xuannhashop.business.shared.*;
import vn.xuannhashop.business.shared.audit.ActivityService;
import vn.xuannhashop.business.shared.security.ActorContext;
@Service public class AccountingService implements AccountingApplication {
    private final AccountingRepository r;private final ActorContext actor;private final Commands commands;private final ActivityService audit;
    public AccountingService(AccountingRepository r,ActorContext actor,Commands commands,ActivityService audit){this.r=r;this.actor=actor;this.commands=commands;this.audit=audit;}
    private void finance(){actor.require("OWNER","ACCOUNTANT");}
    public Map<String,Object> overview(){finance();return r.overview();}
    @Transactional public UUID supplier(String name,String contact,String document,String key){finance();Checks.text(name,160,"Tên nhà cung cấp");Checks.text(contact,300,"Liên hệ");Checks.text(document,180,"Mã hồ sơ nhà cung cấp");return commands.once(key,"SUPPLIER:"+name+":"+contact+":"+document,()->{UUID id=UUID.randomUUID();r.supplier(id,name,contact,document,actor.username());audit.record("SUPPLIER_CREATED",id,name);return id;});}
    @Transactional public UUID expense(Expense c,String key){finance();if(c==null||c.category()==null||!Set.of("PURCHASE","MAINTENANCE","CLEANING","TRANSPORT","OTHER").contains(c.category())||c.incurredOn()==null||c.dueOn()==null||c.incurredOn().isAfter(LocalDate.now())||c.dueOn().isBefore(c.incurredOn()))throw DomainException.bad("Loại, ngày phát sinh hoặc hạn trả không hợp lệ.");Checks.money(c.amount());Checks.text(c.documentRef(),180,"Chứng từ");Checks.text(c.description(),1000,"Nội dung chi phí");return commands.once(key,"EXPENSE:"+c,()->{if(c.supplierId()!=null&&!r.supplierExists(c.supplierId()))throw DomainException.missing();if(c.equipmentId()!=null&&!r.equipmentExists(c.equipmentId()))throw DomainException.missing();if(c.purchaseReceiptId()!=null){var p=r.purchase(c.purchaseReceiptId());if(p==null||!p.get("status").equals("ACCEPTED"))throw DomainException.conflict("Lô tiếp nhận chưa được duyệt.");if(!c.category().equals("PURCHASE")||c.amount().compareTo((BigDecimal)p.get("total"))!=0)throw DomainException.bad("Khoản mua phải bằng tổng giá trị lô đã duyệt.");}if(c.category().equals("PURCHASE")&&c.purchaseReceiptId()==null)throw DomainException.bad("Khoản mua thiết bị cần liên kết lô đã tiếp nhận.");UUID id=UUID.randomUUID();r.expense(id,c,actor.username());audit.record("EXPENSE_REQUESTED",id,c.category()+"; "+c.documentRef());return id;});}
    private void pending(Map<String,Object> c){if(c==null)throw DomainException.missing();if(!c.get("status").equals("PENDING"))throw DomainException.conflict("Hồ sơ đã được quyết định.");if(c.get("requested_by").equals(actor.username()))throw DomainException.conflict("Người duyệt phải khác người lập.");}
    @Transactional public void decideExpense(UUID id,boolean accepted,String note,String key){finance();Checks.text(note,1000,"Căn cứ duyệt");commands.once(key,"EXPENSE_DECIDE:"+id+":"+accepted+":"+note,()->{pending(r.expense(id));r.decideExpense(id,accepted,actor.username(),note);audit.record("EXPENSE_DECIDED",id,accepted+"; "+note);return id;});}
    @Transactional public UUID pay(UUID expense,BigDecimal amount,String evidence,String key){finance();Checks.money(amount);Checks.text(evidence,500,"Chứng từ chi thực tế");return commands.once(key,"EXPENSE_PAY:"+expense+":"+amount+":"+evidence,()->{var e=r.expense(expense);if(e==null)throw DomainException.missing();if(!e.get("status").equals("APPROVED"))throw DomainException.conflict("Chỉ chi khoản đã được duyệt.");if(amount.compareTo(((BigDecimal)e.get("amount")).subtract(r.paid(expense)))>0)throw DomainException.conflict("Số chi vượt khoản còn phải trả.");UUID id=UUID.randomUUID();r.pay(id,expense,amount,evidence,actor.username(),key);audit.record("EXPENSE_PAID",expense,amount+"; "+evidence);return id;});}
    private void balance(BigDecimal n){if(n==null||n.scale()>2||n.abs().compareTo(new BigDecimal("999999999999.99"))>0)throw DomainException.bad("Số dư không hợp lệ.");}
    @Transactional public UUID reconcile(Reconciliation c,String key){finance();if(c==null||c.startsAt()==null||c.endsAt()==null||!c.endsAt().isAfter(c.startsAt())||c.endsAt().isAfter(Instant.now())||Duration.between(c.startsAt(),c.endsAt()).compareTo(Duration.ofHours(48))>0)throw DomainException.bad("Đối soát một ca/ngày đã kết thúc, tối đa 48 giờ.");balance(c.openingBalance());balance(c.countedBalance());Checks.text(c.reason(),1000,"Căn cứ kiểm đếm/đối chiếu");return commands.once(key,"RECONCILE:"+c,()->{r.ledgerLock();if(r.overlaps(c.startsAt(),c.endsAt()))throw DomainException.conflict("Khoảng này đã có đối soát được duyệt.");UUID id=UUID.randomUUID();r.reconcile(id,c,r.ledgerSnapshot(c.startsAt(),c.endsAt()),actor.username());audit.record("RECONCILIATION_REQUESTED",id,c.reason());return id;});}
    @Transactional public void decideReconciliation(UUID id,boolean accepted,String note,String key){finance();Checks.text(note,1000,"Kết luận đối soát");commands.once(key,"RECONCILE_DECIDE:"+id+":"+accepted+":"+note,()->{var c=r.reconciliation(id);pending(c);r.ledgerLock();if(accepted){Instant from=(Instant)c.get("starts_at"),to=(Instant)c.get("ends_at");if(r.overlaps(from,to))throw DomainException.conflict("Khoảng đã có biên bản được duyệt.");if(!c.get("ledger_fingerprint").equals(r.ledgerSnapshot(from,to).get("fingerprint")))throw DomainException.conflict("Sổ tiền đã thay đổi; lập đối soát mới.");}r.decideReconciliation(id,accepted,actor.username(),note);audit.record("RECONCILIATION_DECIDED",id,accepted+"; "+note);return id;});}
}
